#include "runtime_rtti.h"
#include <unordered_map>
#include <cassert>
#include <iostream>
struct Reader {std::unordered_map<uintptr_t,unsigned char> bytes;template<class T>bool Read(uintptr_t p,T& out){for(size_t i=0;i<sizeof(T);++i)if(!bytes.count(p+i))return false;for(size_t i=0;i<sizeof(T);++i)((unsigned char*)&out)[i]=bytes[p+i];return true;}template<class T>void Put(uintptr_t p,const T& value){for(size_t i=0;i<sizeof(T);++i)bytes[p+i]=((const unsigned char*)&value)[i];}void String(uintptr_t p,const char* text){for(size_t i=0;i<=strlen(text);++i)Put(p+i,text[i]);}};
int main(){Reader r;uintptr_t base=0x700000000ULL,vptr=base+0x3000,col=base+0x2000;r.Put(vptr-8,col);runtimertti::Locator c{1,0,0,0x4000,0x5000,0x2000};r.Put(col,c);r.String(base+c.typeRva+16,".?AVC_DOTAPlayerController@@");char out[128];assert(runtimertti::Name(r,base,0x10000,vptr,out,128)&&!strcmp(out,"C_DOTAPlayerController"));c.signature=0;r.Put(col,c);assert(!runtimertti::Name(r,base,0x10000,vptr,out,128));c.signature=1;c.selfRva=123;r.Put(col,c);assert(!runtimertti::Name(r,base,0x10000,vptr,out,128));c.selfRva=0x2000;c.offset=8;r.Put(col,c);assert(!runtimertti::Name(r,base,0x10000,vptr,out,128));c.offset=0;c.typeRva=0x10000;r.Put(col,c);assert(!runtimertti::Name(r,base,0x10000,vptr,out,128));c.typeRva=0x4000;r.Put(col,c);r.String(base+c.typeRva+16,".?AVC_DOTAGamerules@@");assert(runtimertti::Name(r,base,0x10000,vptr,out,128)&&!strcmp(out,"C_DOTAGamerules"));r.String(base+c.typeRva+16,".?AVC_DOTAPlayerController@bad@@");assert(!runtimertti::Name(r,base,0x10000,vptr,out,128));std::cout<<"PASS ARM9 runtime MSVC RTTI: current controller vs gamerules type, locator signature/self/type bounds, primary vtable and decorated-name guards. Not live MSVC data.\n";}
